/*
 * A117998  Decimal number generated by the binary bits of the n-th generation
 *          of the Rule 102 elementary cellular automaton.
 * https://oeis.org/A117998
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 15, u64 n <= 31, u128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>

/* Sequence A117998: a(n) = decimal value of the binary string produced
   by the n‑th generation of Rule 102 elementary cellular automaton
   (initial state a single 1).  a(0) = 1.  */

/*--- Cache of computed terms ---------------------------------------*/
static seq_t *cache = NULL;        /* array of sequence values      */
static size_t  cache_len  = 0;     /* number of values stored       */
static size_t  cache_cap  = 0;     /* current allocation capacity   */

/*--- Buffers for one generation of bits --------------------------*/
static uint8_t *row   = NULL;      /* bits of current generation    */
static uint8_t *next  = NULL;      /* buffer for next generation    */
static size_t   row_cap = 0;       /* capacity of row buffers       */

/*--- Rule 102 mapping table --------------------------------------*/
static const uint8_t rule102[8] = {0,1,1,0,0,1,1,0};
/*    abc (left, centre, right) -> output bit
    index = a<<2 | b<<1 | c  */

/*--- Ensure cache can hold values up to index n ------------------*/
static void ensure_cache(size_t n)
{
    if (n >= cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 16;
        while (new_cap <= n) new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache = tmp;
        cache_cap = new_cap;
    }
}

/*--- Ensure buffers can hold at least len bits -------------------*/
static void ensure_row(size_t len)
{
    if (len > row_cap) {
        row_cap = len;
        row  = (uint8_t *)realloc(row,  row_cap * sizeof(uint8_t));
        next = (uint8_t *)realloc(next, row_cap * sizeof(uint8_t));
    }
}

seq_t a(idx_t n)
{
    /* Return cached value if already known. */
    if (n < cache_len) return cache[n];

    /* Initialisation: generation 0. */
    if (cache_len == 0) {
        ensure_row(1);
        row[0] = 1;
        seq_t v = 1;
        ensure_cache(0);
        cache[0] = v;
        cache_len = 1;
    }

    /* Compute generations from cache_len to n. */
    for (idx_t g = cache_len; g <= n; ++g) {
        size_t prev_len = 2 * (g - 1) + 1;   /* width of previous gen   */
        size_t new_len  = 2 * g + 1;         /* width of current gen    */

        ensure_row(new_len);

        /* Build next row: each bit depends on
           row[i‑2], row[i‑1], row[i] (with zeros outside bounds). */
        for (size_t i = 0; i < new_len; ++i) {
            uint8_t a_bit = (i >= 2) ? row[i - 2] : 0;
            uint8_t b_bit = (i >= 1 && i - 1 < prev_len) ? row[i - 1] : 0;
            uint8_t c_bit = (i < prev_len) ? row[i] : 0;
            next[i] = rule102[(a_bit << 2) | (b_bit << 1) | c_bit];
        }

        /* Compute decimal value of the binary string (most significant
           bit is next[0]). */
        seq_t val = 0;
        for (size_t i = 0; i < new_len; ++i) {
            val = (val << 1) | next[i];
        }

        /* Store the computed value. */
        ensure_cache(cache_len);
        cache[cache_len++] = val;

        /* Prepare for next iteration: next becomes the current row. */
        uint8_t *swap = row;
        row = next;
        next = swap;
    }

    return cache[n];
}
